-- Independently written starter questions. Clinician review required before charging customers.
-- This file is idempotent: previously edited questions are preserved.
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('fop-001','FOP','Respiratory','Foundation','An 8-month-old has coryza followed by cough, wheeze and fine inspiratory crackles in winter. What is the most likely diagnosis?','["Foreign-body aspiration","Pulmonary oedema","Acute bronchiolitis","Bacterial epiglottitis","Acute laryngitis"]',2,'Bronchiolitis is a clinical diagnosis in infants, usually following an upper respiratory prodrome and featuring wheeze or crackles. The degree of work of breathing and hydration determine management.','NICE guideline NG9: Bronchiolitis in children','https://www.nice.org.uk/guidance/ng9',1,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('fop-002','FOP','Respiratory','Foundation','A 2-year-old has a barking cough, hoarse voice and inspiratory stridor after a viral prodrome. Which diagnosis best fits?','["Viral croup","Pertussis","Bacterial pneumonia","Bronchiolitis","Asthma exacerbation"]',0,'Croup causes upper-airway inflammation, producing barking cough, hoarseness and often inspiratory stridor. Assess severity and airway distress before choosing treatment.','NHS: Croup overview','https://www.nhs.uk/conditions/croup/',1,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('fop-003','FOP','Cardiology','Foundation','A child has a harsh pansystolic murmur loudest at the lower left sternal border. Which lesion is most likely?','["Pulmonary valve stenosis","Atrial septal defect","Patent ductus arteriosus","Coarctation of the aorta","Ventricular septal defect"]',4,'A ventricular septal defect produces a pansystolic murmur at the lower left sternal edge as blood flows from the left to right ventricle during systole.','RCPCH theory exam syllabus and structure','https://www.rcpch.ac.uk/education-careers/examinations/theory/structure-syllabi',1,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('fop-004','FOP','Cardiology','Foundation','An asymptomatic school-aged child has a fixed split second heart sound and an ejection systolic murmur at the upper left sternal edge. Which diagnosis is likely?','["Aortic regurgitation","Ventricular septal defect","Mitral stenosis","Atrial septal defect","Patent ductus arteriosus"]',3,'A fixed split second heart sound is characteristic of an atrial septal defect because right ventricular filling varies little with respiration in the presence of the shunt.','RCPCH theory exam syllabus and structure','https://www.rcpch.ac.uk/education-careers/examinations/theory/structure-syllabi',1,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('fop-005','FOP','Cardiology','Intermediate','A school child is hypertensive in both arms but has weak femoral pulses and lower blood pressure in the legs. What is the most likely condition?','["Atrial septal defect","Patent ductus arteriosus","Mitral regurgitation","Coarctation of the aorta","Pulmonary hypertension"]',3,'Coarctation creates an obstruction distal to vessels supplying the arms, resulting in higher upper-limb pressure and delayed or diminished femoral pulses.','RCPCH theory exam syllabus and structure','https://www.rcpch.ac.uk/education-careers/examinations/theory/structure-syllabi',1,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('fop-006','FOP','Cardiology','Foundation','A continuous machinery-like murmur is heard beneath the left clavicle in a preterm infant. Which lesion is classically responsible?','["Aortic stenosis","Pulmonary stenosis","Ventricular septal defect","Patent ductus arteriosus","Tricuspid regurgitation"]',3,'A persistent ductus permits blood flow between aorta and pulmonary artery through systole and diastole, generating a continuous murmur.','RCPCH theory exam syllabus and structure','https://www.rcpch.ac.uk/education-careers/examinations/theory/structure-syllabi',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('fop-007','FOP','Neonatology','Foundation','A well term neonate develops visible jaundice at 8 hours of life. Which statement is most appropriate?','["This is always physiological jaundice","No bilirubin measurement is necessary","Phototherapy is never required before day three","Jaundice within the first 24 hours requires urgent assessment","Breast milk jaundice is the most likely cause"]',3,'Jaundice in the first 24 hours is not considered physiological and warrants prompt measurement of bilirubin and investigation according to the clinical context.','NICE guideline CG98: Jaundice in newborn babies','https://www.nice.org.uk/guidance/cg98',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('fop-008','FOP','Gastroenterology','Foundation','A 5-week-old has progressive projectile non-bilious vomiting and persistent hunger. Which acid-base abnormality is classically expected?','["Respiratory acidosis","High anion-gap metabolic acidosis","Respiratory alkalosis","Hypochloraemic metabolic alkalosis","Hyperchloraemic metabolic acidosis"]',3,'Gastric hydrochloric acid loss in hypertrophic pyloric stenosis leads to hypochloraemic, often hypokalaemic, metabolic alkalosis.','RCPCH theory exam syllabus and structure','https://www.rcpch.ac.uk/education-careers/examinations/theory/structure-syllabi',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('fop-009','FOP','Gastroenterology','Intermediate','A 9-month-old has episodes of severe colicky abdominal pain, pulls the knees up and then appears comfortable between episodes. What is an important diagnosis to exclude?','["Infantile colic","Gastro-oesophageal reflux","Functional constipation","Intussusception","Meckel diverticulum without complications"]',3,'Intussusception commonly causes intermittent severe abdominal pain with periods of apparent improvement. Bloody stool can develop but is not always present.','RCPCH theory exam syllabus and structure','https://www.rcpch.ac.uk/education-careers/examinations/theory/structure-syllabi',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('fop-010','FOP','Gastroenterology','Foundation','A newborn has abdominal distension and does not pass meconium in the first 48 hours. Rectal biopsy later shows no ganglion cells. What is the diagnosis?','["Necrotising enterocolitis","Meconium ileus due solely to dietary factors","Pyloric stenosis","Hirschsprung disease","Malrotation without volvulus"]',3,'Hirschsprung disease is caused by congenital absence of enteric ganglion cells, producing functional distal intestinal obstruction.','RCPCH theory exam syllabus and structure','https://www.rcpch.ac.uk/education-careers/examinations/theory/structure-syllabi',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('fop-011','FOP','Endocrinology','Foundation','A young infant has poor feeding, prolonged jaundice, hypotonia and a large tongue. Which treatable endocrine diagnosis must be considered?','["Hyperthyroidism","Diabetes insipidus","Congenital adrenal hyperplasia alone","Hyperparathyroidism","Congenital hypothyroidism"]',4,'Congenital hypothyroidism can present with prolonged jaundice, hypotonia and macroglossia; early identification and levothyroxine treatment prevent neurodevelopmental harm.','RCPCH theory exam syllabus and structure','https://www.rcpch.ac.uk/education-careers/examinations/theory/structure-syllabi',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('fop-012','FOP','Endocrinology','Foundation','A child has polyuria, polydipsia, weight loss and hyperglycaemia. Which additional finding establishes diabetic ketoacidosis?','["Raised HbA1c alone","A positive family history of diabetes","Glucose in urine without ketones","Ketonaemia with metabolic acidosis","Isolated mild dehydration"]',3,'DKA is defined by hyperglycaemia, ketonaemia or significant ketonuria, and metabolic acidosis. Hyperglycaemia alone does not establish DKA.','NICE guideline NG18: Diabetes in children and young people','https://www.nice.org.uk/guidance/ng18',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('fop-013','FOP','Renal','Foundation','A child develops periorbital oedema, marked proteinuria and low plasma albumin with preserved blood pressure. Which syndrome is most likely?','["Diabetes insipidus","Renal tubular acidosis","Acute glomerular failure without proteinuria","Nephrotic syndrome","Nephritic syndrome"]',3,'Nephrotic syndrome features heavy proteinuria causing hypoalbuminaemia and oedema; children may have hyperlipidaemia as well.','RCPCH theory exam syllabus and structure','https://www.rcpch.ac.uk/education-careers/examinations/theory/structure-syllabi',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('fop-014','FOP','Renal','Intermediate','A 7-year-old develops palpable purpura on the legs, ankle pain and colicky abdominal pain after a respiratory illness. What is the most likely diagnosis?','["Juvenile dermatomyositis","Meningococcal septicaemia without systemic illness","Immune thrombocytopenia alone","IgA vasculitis","Scarlet fever"]',3,'IgA vasculitis causes non-thrombocytopenic palpable purpura, often with joint, abdominal and renal involvement. Urine and blood pressure assessment are important.','RCPCH theory exam syllabus and structure','https://www.rcpch.ac.uk/education-careers/examinations/theory/structure-syllabi',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('fop-015','FOP','Infectious diseases','Foundation','A child has at least 5 days of fever, bilateral non-purulent conjunctivitis, cracked lips and swollen hands. Which diagnosis should be considered?','["Scarlet fever alone","Measles without a rash","Rubella","Kawasaki disease","Roseola infantum"]',3,'Kawasaki disease is a systemic vasculitis associated with prolonged fever and mucocutaneous features. Recognition matters because untreated inflammation can damage coronary arteries.','RCPCH theory exam syllabus and structure','https://www.rcpch.ac.uk/education-careers/examinations/theory/structure-syllabi',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('fop-016','FOP','Haematology','Foundation','A toddler who drinks large quantities of cow''s milk has pallor, low haemoglobin and low mean corpuscular volume. What is the most likely deficiency?','["Folate deficiency","Factor VIII deficiency","Vitamin K deficiency","Iron deficiency","Vitamin B12 deficiency"]',3,'Excess cow''s milk intake can displace iron-rich foods in toddlers; iron deficiency commonly causes microcytic, hypochromic anaemia.','RCPCH theory exam syllabus and structure','https://www.rcpch.ac.uk/education-careers/examinations/theory/structure-syllabi',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('fop-017','FOP','Haematology','Intermediate','A 12-month-old with sickle cell disease develops painful swelling of both hands and feet. What is this manifestation called?','["Rickets","Reactive arthritis","Erythema nodosum","Dactylitis","Haemarthrosis"]',3,'Sickle cell dactylitis is painful infarction affecting small bones of the hands and feet, often an early manifestation of HbSS in infancy.','RCPCH theory exam syllabus and structure','https://www.rcpch.ac.uk/education-careers/examinations/theory/structure-syllabi',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('fop-018','FOP','Genetics','Foundation','A neonate has hypotonia, characteristic facial features and a single transverse palmar crease. Which chromosomal condition is most likely?','["Trisomy 18","Trisomy 13","Klinefelter syndrome","Trisomy 21","Monosomy X"]',3,'Down syndrome is most commonly caused by trisomy 21. Diagnosis requires appropriate chromosomal testing rather than appearance alone.','RCPCH theory exam syllabus and structure','https://www.rcpch.ac.uk/education-careers/examinations/theory/structure-syllabi',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('fop-019','FOP','Genetics','Foundation','A girl has short stature, a webbed neck and coarctation of the aorta. Which chromosomal abnormality is most associated?','["47,XXX","47,XXY","Trisomy 21","Trisomy 18","45,X"]',4,'Turner syndrome often has a 45,X karyotype and may feature short stature and congenital left-sided cardiac lesions.','RCPCH theory exam syllabus and structure','https://www.rcpch.ac.uk/education-careers/examinations/theory/structure-syllabi',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('fop-020','FOP','Immunology','Intermediate','An infant has recurrent severe infections and profound T-cell lymphopenia. Which immunisation category should usually be avoided pending specialist advice?','["Recombinant protein vaccines","Toxoid vaccines","Inactivated vaccines","Live attenuated vaccines","Non-live conjugate vaccines"]',3,'Severe cellular immunodeficiency substantially increases the risk of disease from live attenuated vaccines. Specialist assessment is required before immunisation decisions.','RCPCH theory exam syllabus and structure','https://www.rcpch.ac.uk/education-careers/examinations/theory/structure-syllabi',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('fop-021','FOP','Development','Foundation','Which developmental skill is most typical around 9 months of age?','["Reading simple words","Drawing a circle","Jumping with both feet","Sitting independently","Using full sentences"]',3,'Many infants can sit without support by around 9 months. Milestones vary; developmental surveillance considers the overall pattern and corrected age when appropriate.','RCPCH theory exam syllabus and structure','https://www.rcpch.ac.uk/education-careers/examinations/theory/structure-syllabi',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('fop-022','FOP','Development','Foundation','A child aged 2 years has limited speech but good social interaction. Which assessment is especially important in the initial evaluation?','["Routine CT brain for every child","Immediate diagnosis of autism spectrum disorder","Routine muscle biopsy","Formal hearing assessment","Routine chromosomal microarray for all children"]',3,'Hearing impairment can contribute to speech delay, so hearing assessment is an important part of evaluation even when newborn screening was normal.','RCPCH theory exam syllabus and structure','https://www.rcpch.ac.uk/education-careers/examinations/theory/structure-syllabi',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('fop-023','FOP','Respiratory','Intermediate','A previously well toddler starts coughing suddenly while eating peanuts and has persistent unilateral wheeze. What diagnosis needs urgent consideration?','["Simple laryngomalacia","Idiopathic pulmonary fibrosis","Typical viral bronchiolitis","Airway foreign-body aspiration","Allergic rhinitis"]',3,'A sudden choking episode followed by focal wheeze strongly suggests an inhaled foreign body. A normal radiograph does not exclude it.','RCPCH theory exam syllabus and structure','https://www.rcpch.ac.uk/education-careers/examinations/theory/structure-syllabi',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('fop-024','FOP','Musculoskeletal','Foundation','A toddler with bowed legs, widened wrists and delayed walking has low vitamin D intake. What metabolic bone disorder is most likely?','["Osteogenesis imperfecta","Septic arthritis","Juvenile idiopathic arthritis","Osteopetrosis","Nutritional rickets"]',4,'Vitamin D deficiency can impair mineralisation at growth plates, producing rachitic skeletal changes and sometimes hypocalcaemia.','RCPCH theory exam syllabus and structure','https://www.rcpch.ac.uk/education-careers/examinations/theory/structure-syllabi',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('fop-025','FOP','Gastroenterology','Intermediate','A child has chronic diarrhoea, abdominal distension and faltering growth. Coeliac disease is suspected. Which first-line serological test is commonly used when the child eats gluten?','["Serum amylase alone","Stool occult blood alone","Anti-dsDNA","Total IgA and IgA tissue transglutaminase","Serum gastrin"]',3,'Coeliac screening commonly uses total IgA together with IgA anti-tTG while the patient consumes gluten; IgA deficiency alters the testing strategy.','NICE guideline NG20: Coeliac disease','https://www.nice.org.uk/guidance/ng20',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('fop-026','FOP','Infectious diseases','Intermediate','A febrile child has a bulging, opaque tympanic membrane and recent ear pain. Which diagnosis is most consistent?','["Mastoiditis without middle-ear findings","Eustachian tube dysfunction without infection","Otitis externa","Acute otitis media","Cholesteatoma alone"]',3,'Bulging of the tympanic membrane with acute symptoms strongly supports acute otitis media rather than simple redness alone.','RCPCH theory exam syllabus and structure','https://www.rcpch.ac.uk/education-careers/examinations/theory/structure-syllabi',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('fop-027','FOP','Cardiology','Intermediate','A child with tetralogy of Fallot suddenly becomes deeply cyanotic during crying. Which immediate positioning manoeuvre may help while urgent treatment is arranged?','["Flat supine position with legs lowered","Prone position without monitoring","Trendelenburg as sole management","Forced sitting upright only","Knee-chest position"]',4,'The knee-chest position increases systemic vascular resistance and may reduce right-to-left shunting during a hypercyanotic spell. This is an emergency requiring prompt specialist management.','RCPCH theory exam syllabus and structure','https://www.rcpch.ac.uk/education-careers/examinations/theory/structure-syllabi',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('fop-028','FOP','Renal','Intermediate','A child has tea-coloured urine, oedema and hypertension two weeks after streptococcal pharyngitis. What renal process is most likely?','["Isolated renal glycosuria","Minimal change nephrotic syndrome","Acute post-streptococcal glomerulonephritis","Simple asymptomatic bacteriuria","Diabetes insipidus"]',2,'Post-streptococcal glomerulonephritis presents with nephritic features such as haematuria, hypertension and oedema after a preceding infection.','RCPCH theory exam syllabus and structure','https://www.rcpch.ac.uk/education-careers/examinations/theory/structure-syllabi',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('fop-029','FOP','Neonatology','Foundation','A term baby has cyanosis that does not improve adequately with oxygen and a loud single second heart sound. Which broad diagnostic category should be urgently considered?','["Cyanotic congenital heart disease","Physiological reflux","Benign neonatal murmur alone","Iron deficiency anaemia","Simple neonatal acne"]',0,'Persistent central cyanosis in a neonate requires immediate assessment for cardiac, respiratory and other causes; cyanotic congenital cardiac defects are an important consideration.','RCPCH theory exam syllabus and structure','https://www.rcpch.ac.uk/education-careers/examinations/theory/structure-syllabi',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('fop-030','FOP','Nutrition','Foundation','Which nutrient supplementation is particularly important to prevent neural-tube defects when planning pregnancy?','["Folic acid","Vitamin C alone","Vitamin K alone","Iron only after delivery","Magnesium alone"]',0,'Periconceptional folic acid reduces neural-tube defect risk. Higher doses may be indicated for selected high-risk pregnancies according to local guidance.','RCPCH theory exam syllabus and structure','https://www.rcpch.ac.uk/education-careers/examinations/theory/structure-syllabi',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('tas-001','TAS','Respiratory physiology','Foundation','Which variable has the strongest direct inverse relationship with arterial carbon dioxide tension when carbon dioxide production is constant?','["Heart rate","Functional residual capacity","Alveolar ventilation","Total lung capacity","Haemoglobin concentration"]',2,'Arterial PaCO2 is inversely proportional to alveolar ventilation when metabolic CO2 production remains constant. Hypoventilation raises PaCO2.','NCBI Bookshelf: Biomedical science reference collection','https://www.ncbi.nlm.nih.gov/books/',1,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('tas-002','TAS','Respiratory physiology','Foundation','Which change shifts the haemoglobin oxygen dissociation curve to the right?','["Reduced hydrogen-ion concentration","Reduced 2,3-BPG","Reduced temperature","Increased pH","Increased carbon dioxide tension"]',4,'Higher CO2, lower pH, higher temperature and increased 2,3-BPG reduce haemoglobin oxygen affinity, shifting the curve to the right and facilitating oxygen unloading.','NCBI Bookshelf: Biomedical science reference collection','https://www.ncbi.nlm.nih.gov/books/',1,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('tas-003','TAS','Respiratory physiology','Foundation','Compared with adult haemoglobin, fetal haemoglobin has which property?','["Higher oxygen affinity","Lower oxygen affinity","No ability to bind oxygen","Identical subunit composition","Higher 2,3-BPG affinity"]',0,'Fetal haemoglobin (alpha2 gamma2) binds 2,3-BPG less strongly, increasing oxygen affinity and facilitating placental oxygen transfer.','NCBI Bookshelf: Biomedical science reference collection','https://www.ncbi.nlm.nih.gov/books/',1,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('tas-004','TAS','Blood gases','Intermediate','An adolescent has pH 7.24, bicarbonate 12 mmol/L and PaCO2 27 mmHg. Which primary acid-base disturbance is present?','["Mixed metabolic alkalosis and respiratory acidosis","Metabolic alkalosis","Metabolic acidosis","Respiratory acidosis","Respiratory alkalosis"]',2,'Low pH with low bicarbonate indicates primary metabolic acidosis. Low PaCO2 is compatible with compensatory hyperventilation.','NCBI Bookshelf: Biomedical science reference collection','https://www.ncbi.nlm.nih.gov/books/',1,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('tas-005','TAS','Blood gases','Foundation','Which formula gives the conventional plasma anion gap when potassium is excluded?','["Potassium minus chloride alone","Sodium plus bicarbonate plus chloride","Chloride plus bicarbonate minus sodium","Bicarbonate divided by sodium","Sodium minus the sum of chloride and bicarbonate"]',4,'The common anion-gap calculation is Na - (Cl + HCO3), with all concentrations in consistent units. Reference ranges depend on local methods and albumin.','NCBI Bookshelf: Biomedical science reference collection','https://www.ncbi.nlm.nih.gov/books/',1,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('tas-006','TAS','Renal physiology','Foundation','Which nephron segment reabsorbs sodium, potassium and chloride while being relatively impermeable to water?','["Thin descending limb of Henle","Thick ascending limb of the loop of Henle","Collecting duct under maximal antidiuresis","Distal ureter","Bowman''s space"]',1,'The thick ascending limb uses NKCC2 to reabsorb solutes without water, contributing to the medullary gradient and dilution of tubular fluid.','NCBI Bookshelf: Biomedical science reference collection','https://www.ncbi.nlm.nih.gov/books/',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('tas-007','TAS','Renal physiology','Foundation','Antidiuretic hormone increases water permeability in which nephron segment by inserting aquaporin-2 channels?','["Ascending limb intercalated cells","Macula densa cells","Collecting duct principal cells","Glomerular podocytes","Proximal tubular brush border"]',2,'ADH acts through V2 receptors on collecting duct principal cells, promoting aquaporin-2 insertion and increasing water reabsorption.','NCBI Bookshelf: Biomedical science reference collection','https://www.ncbi.nlm.nih.gov/books/',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('tas-008','TAS','Renal physiology','Intermediate','Which immediate glomerular effect is expected when the afferent arteriole constricts substantially?','["Unchanged glomerular capillary pressure with higher GFR","Reduced renal plasma flow and generally reduced GFR","Increased renal plasma flow","Increased filtration fraction from higher inflow","Complete absence of sodium handling"]',1,'Afferent arteriolar constriction decreases blood entering the glomerulus and lowers capillary hydrostatic pressure, generally reducing GFR.','NCBI Bookshelf: Biomedical science reference collection','https://www.ncbi.nlm.nih.gov/books/',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('tas-009','TAS','Endocrinology','Foundation','Which hormone primarily promotes insulin-independent hepatic glycogen breakdown during fasting?','["Insulin","Glucagon","Oxytocin","Prolactin","Calcitonin"]',1,'Glucagon signals through the hepatic G-protein–cAMP pathway to stimulate glycogenolysis and gluconeogenesis during fasting.','NCBI Bookshelf: Biomedical science reference collection','https://www.ncbi.nlm.nih.gov/books/',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('tas-010','TAS','Endocrinology','Intermediate','Insulin increases glucose uptake into skeletal muscle principally by promoting translocation of which transporter?','["SGLT2","GLUT2 at the apical border","CFTR","GLUT5","GLUT4"]',4,'Insulin stimulates translocation of GLUT4 transporters to the surface of skeletal muscle and adipose cells, facilitating glucose uptake.','NCBI Bookshelf: Biomedical science reference collection','https://www.ncbi.nlm.nih.gov/books/',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('tas-011','TAS','Endocrinology','Foundation','Which pituitary response would be expected in untreated primary hypothyroidism?','["Normal TSH in every patient","Raised TSH","Suppressed TSH with elevated free T4","Suppressed prolactin as the defining feature","Raised ACTH as the primary feature"]',1,'Low thyroid hormone removes negative feedback from the hypothalamic-pituitary axis, usually increasing TSH in primary hypothyroidism.','NCBI Bookshelf: Biomedical science reference collection','https://www.ncbi.nlm.nih.gov/books/',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('tas-012','TAS','Endocrinology','Intermediate','Which hormone is the major endocrine mediator of many growth hormone effects on linear growth?','["Aldosterone","Calcitonin","Insulin-like growth factor 1","Renin","Parathyroid hormone"]',2,'Growth hormone stimulates production of IGF-1, mainly in the liver and locally in tissues; IGF-1 contributes to chondrocyte proliferation and skeletal growth.','NCBI Bookshelf: Biomedical science reference collection','https://www.ncbi.nlm.nih.gov/books/',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('tas-013','TAS','Endocrinology','Foundation','Which ion is directly regulated by parathyroid hormone through effects on bone, kidneys and vitamin D activation?','["Iron","Bicarbonate alone","Chloride alone","Magnesium only","Calcium"]',4,'Parathyroid hormone generally increases serum calcium by stimulating renal calcium retention, bone resorption and activation of vitamin D, while promoting phosphate excretion.','NCBI Bookshelf: Biomedical science reference collection','https://www.ncbi.nlm.nih.gov/books/',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('tas-014','TAS','Endocrinology','Intermediate','An infant has hyponatraemia, low plasma osmolality and inappropriately concentrated urine without clinical dehydration. Which hormonal action best explains the findings?','["Excess antidiuretic hormone activity","Complete ADH deficiency","Excess atrial natriuretic peptide as sole cause","Glucagon excess","Insulin deficiency"]',0,'Excess ADH promotes water retention, lowering serum sodium and osmolality while preventing appropriately dilute urine. Diagnosis of SIADH requires exclusion of other causes.','NCBI Bookshelf: Biomedical science reference collection','https://www.ncbi.nlm.nih.gov/books/',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('tas-015','TAS','Genetics','Foundation','A mother carries a pathogenic X-linked recessive variant and the father is unaffected. What is the risk to each son of inheriting the variant?','["25 percent","100 percent","50 percent","75 percent","0 percent"]',2,'Each son inherits his X chromosome from his mother, so an unaffected father does not alter the mother''s 50 percent transmission probability to each son.','NCBI Bookshelf: Biomedical science reference collection','https://www.ncbi.nlm.nih.gov/books/',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('tas-016','TAS','Genetics','Foundation','Which inheritance pattern characteristically passes an affected mitochondrial DNA variant through mothers rather than fathers?','["Mitochondrial inheritance","Autosomal recessive inheritance","Autosomal dominant inheritance","X-linked dominant inheritance","Y-linked inheritance"]',0,'Human mitochondrial DNA is typically maternally inherited. Heteroplasmy can cause variable expression among maternal relatives.','NCBI Bookshelf: Biomedical science reference collection','https://www.ncbi.nlm.nih.gov/books/',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('tas-017','TAS','Genetics','Intermediate','A parent is heterozygous for a fully penetrant autosomal dominant variant. What is the transmission probability for each child?','["50 percent","10 percent","100 percent","75 percent","25 percent"]',0,'An affected heterozygous parent has one mutant and one unaffected allele, giving a 1-in-2 transmission probability per pregnancy independently of previous births.','NCBI Bookshelf: Biomedical science reference collection','https://www.ncbi.nlm.nih.gov/books/',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('tas-018','TAS','Epidemiology','Foundation','Sensitivity of a diagnostic test is calculated using which ratio?','["All positive tests divided by all tests","True negatives divided by all people without disease","True positives divided by all negative tests","False positives divided by all positive tests","True positives divided by all people who truly have the disease"]',4,'Sensitivity is TP/(TP+FN), the probability that a test is positive among people who have the target condition.','NCBI Bookshelf: Biomedical science reference collection','https://www.ncbi.nlm.nih.gov/books/',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('tas-019','TAS','Epidemiology','Foundation','Specificity of a diagnostic test is calculated using which ratio?','["True negatives divided by all people without the disease","True positives divided by false positives","True positives divided by all people with the disease","False negatives divided by all diseased people","All negative tests divided by all tests"]',0,'Specificity is TN/(TN+FP), the probability of a negative test among people who do not have the condition.','NCBI Bookshelf: Biomedical science reference collection','https://www.ncbi.nlm.nih.gov/books/',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('tas-020','TAS','Epidemiology','Intermediate','If sensitivity and specificity remain constant, what usually happens to the positive predictive value when disease prevalence increases?','["It increases","It becomes equal to specificity","It remains exactly unchanged","It becomes equal to sensitivity","It always decreases"]',0,'As prevalence rises, positive results contain a greater proportion of true positives, generally increasing positive predictive value.','NCBI Bookshelf: Biomedical science reference collection','https://www.ncbi.nlm.nih.gov/books/',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('tas-021','TAS','Research methods','Foundation','What is the main purpose of random allocation in a clinical trial?','["To ensure participants are blinded","To remove the need for statistical analysis","To eliminate all loss to follow-up","To guarantee the treatment works","To reduce systematic baseline differences between treatment groups"]',4,'Randomisation helps balance measured and unmeasured confounders on average and reduces selection bias in treatment assignment.','NCBI Bookshelf: Biomedical science reference collection','https://www.ncbi.nlm.nih.gov/books/',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('tas-022','TAS','Research methods','Intermediate','A 95 percent confidence interval for the difference between two means includes zero. Which interpretation is most appropriate for a conventional two-sided test at the 5 percent level?','["The probability the null hypothesis is true is 95 percent","The result is not statistically significant at the 5 percent level","The intervention is proven identical to control","The study is necessarily underpowered","The treatment effect must be harmful"]',1,'When the 95 percent confidence interval for a mean difference includes zero, the corresponding two-sided p-value is generally at least 0.05. This does not establish equivalence.','NCBI Bookshelf: Biomedical science reference collection','https://www.ncbi.nlm.nih.gov/books/',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('tas-023','TAS','Immunology','Foundation','Which antibody class provides a major component of mucosal immunity in secretions such as breast milk?','["IgG4 exclusively","Secretory IgA","IgM only","IgD","IgE"]',1,'Secretory IgA helps protect mucosal surfaces by neutralising pathogens, including in breast milk and respiratory and gastrointestinal secretions.','NCBI Bookshelf: Biomedical science reference collection','https://www.ncbi.nlm.nih.gov/books/',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('tas-024','TAS','Immunology','Foundation','Which immunoglobulin class crosses the placenta most efficiently to provide passive systemic immunity to the fetus?','["IgA","IgM","IgG","IgE","IgD"]',2,'IgG crosses the placenta via neonatal Fc receptors, giving the neonate maternally derived systemic antibody protection.','NCBI Bookshelf: Biomedical science reference collection','https://www.ncbi.nlm.nih.gov/books/',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('tas-025','TAS','Immunology','Foundation','Immediate allergic anaphylaxis is classically mediated by which immunological mechanism?','["Complement deficiency alone","IgE-mediated mast-cell degranulation","IgG-driven immune-complex deposition only","Antibody-independent cytotoxic T-cell action","T-cell delayed hypersensitivity alone"]',1,'In type I hypersensitivity, antigen cross-links IgE bound to mast cells, triggering mediator release. Non-IgE mechanisms may also cause anaphylaxis.','NCBI Bookshelf: Biomedical science reference collection','https://www.ncbi.nlm.nih.gov/books/',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('tas-026','TAS','Microbiology','Foundation','Lipopolysaccharide endotoxin is primarily a structural component of which organisms?','["Viruses","Protozoa","Gram-positive bacteria exclusively","Fungi","Gram-negative bacteria"]',4,'LPS is found in the outer membrane of Gram-negative bacteria and can activate innate immune pathways that contribute to inflammation and shock.','NCBI Bookshelf: Biomedical science reference collection','https://www.ncbi.nlm.nih.gov/books/',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('tas-027','TAS','Pharmacology','Intermediate','For a drug with first-order elimination, approximately how many half-lives are needed to reach around 94 to 97 percent of steady-state plasma concentration during constant dosing?','["One tenth of a half-life","One hundred half-lives","Four to five half-lives","Exactly one half-life","Twenty half-lives in every case"]',2,'With first-order pharmacokinetics, successive half-lives bring concentrations progressively closer to steady state; about 4–5 half-lives reach roughly 94–97 percent.','NCBI Bookshelf: Biomedical science reference collection','https://www.ncbi.nlm.nih.gov/books/',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('tas-028','TAS','Pharmacology','Foundation','Which formula defines the apparent volume of distribution after intravenous dosing?','["Oral bioavailability multiplied by dose","Amount of drug in body divided by plasma drug concentration","Glomerular filtration rate multiplied by time","Urinary concentration divided by plasma concentration","Plasma clearance divided by half-life"]',1,'Apparent volume of distribution relates the amount of drug in the body to the measured plasma concentration. It need not correspond to a real anatomical volume.','NCBI Bookshelf: Biomedical science reference collection','https://www.ncbi.nlm.nih.gov/books/',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('tas-029','TAS','Pharmacology','Foundation','An orally administered drug undergoes substantial first-pass hepatic metabolism. What is the usual effect on systemic bioavailability?','["Complete absence of plasma protein binding","Guaranteed complete bioavailability","No effect in any situation","Increased bioavailability to above 100 percent","Reduced bioavailability"]',4,'First-pass metabolism can remove a portion of orally absorbed drug before it reaches systemic circulation, reducing bioavailability.','NCBI Bookshelf: Biomedical science reference collection','https://www.ncbi.nlm.nih.gov/books/',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('tas-030','TAS','Cardiovascular physiology','Intermediate','Which change most directly increases cardiac output if heart rate stays constant?','["Reduced venous return with unchanged contractility","Reduced stroke volume","Increased stroke volume","Higher systemic vascular resistance alone","Increased end-systolic volume without change in end-diastolic volume"]',2,'Cardiac output equals heart rate multiplied by stroke volume. If heart rate is constant, raising stroke volume increases output.','NCBI Bookshelf: Biomedical science reference collection','https://www.ncbi.nlm.nih.gov/books/',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('akp-001','AKP','Emergency medicine','Advanced','A 3-year-old is febrile, lethargic, poorly perfused and has a rapidly spreading non-blanching rash. What is the most appropriate next step?','["Activate emergency sepsis management immediately","Delay antibiotics until culture results are available","Arrange routine outpatient dermatology review","Wait for the rash to resolve","Discharge with oral antipyretics"]',0,'Suspected meningococcal sepsis with shock is time-critical. Immediate airway, breathing, circulation assessment, resuscitation, urgent antimicrobials and senior critical-care involvement are essential.','NICE guideline NG51: Sepsis','https://www.nice.org.uk/guidance/ng51',1,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('akp-002','AKP','Emergency medicine','Advanced','A child develops wheeze, hypotension and lip swelling shortly after eating a new food. What is the first-line drug and route for suspected anaphylaxis?','["Intramuscular adrenaline into the anterolateral thigh","Intravenous chlorphenamine alone","Nebulised salbutamol alone","Oral prednisolone alone","Subcutaneous insulin"]',0,'Intramuscular adrenaline is first-line for anaphylaxis; treat promptly while calling for help and supporting airway, breathing and circulation. Antihistamines and steroids must not delay adrenaline.','Resuscitation Council UK guidelines','https://www.resus.org.uk/library',1,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('akp-003','AKP','Emergency medicine','Intermediate','An alert infant under one year is choking on a solid object, cannot cry and has an ineffective cough. Which sequence is recommended initially?','["Immediate oral fluids","Abdominal thrusts only","Cycles of five back blows and five chest thrusts","Encouraging the child to lie down and sleep","Blind finger sweeps"]',2,'For severe foreign-body airway obstruction in a conscious infant, give up to five back blows alternating with up to five chest thrusts. Avoid abdominal thrusts and blind finger sweeps in infants.','Resuscitation Council UK guidelines','https://www.resus.org.uk/library',1,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('akp-004','AKP','Emergency medicine','Advanced','A 7-year-old with diabetic ketoacidosis develops worsening headache, reduced consciousness and an unexpected fall in heart rate during treatment. What life-threatening complication is most concerning?','["Uncomplicated otitis media","Transient peripheral neuropathy","Simple migraine","Iron deficiency anaemia","Cerebral oedema or cerebral injury"]',4,'New neurological deterioration during DKA treatment can indicate cerebral injury. Immediate senior review and emergency treatment are needed; do not delay for imaging if clinically suspected.','NICE guideline NG18: Diabetes in children and young people','https://www.nice.org.uk/guidance/ng18',1,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('akp-005','AKP','Emergency medicine','Intermediate','A shocked child remains hypotensive with delayed capillary refill and a fast pulse. What is the best general principle?','["Provide immediate ABC assessment and resuscitation with repeated reassessment","Wait for blood culture before obtaining intravenous access","Discharge if the child is awake","Start oral fluids as the only management","Ignore blood pressure because children compensate"]',0,'Shock requires rapid structured assessment and treatment of the underlying cause, with repeated reassessment and early senior or critical-care support.','NICE guideline NG51: Sepsis','https://www.nice.org.uk/guidance/ng51',1,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('akp-006','AKP','Respiratory','Intermediate','A 2-year-old with a barking cough has significant stridor at rest and marked chest recession. What approach is most appropriate?','["Chest physiotherapy as first-line treatment","Forceful throat examination","Urgent assessment with corticosteroid and consideration of nebulised adrenaline according to severity","Routine oral antibiotics in every case","Reassurance without monitoring"]',2,'Stridor at rest and marked retractions suggest more severe croup. Give appropriate corticosteroid and escalate care; nebulised adrenaline may be used for significant respiratory distress.','NHS: Croup overview','https://www.nhs.uk/conditions/croup/',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('akp-007','AKP','Respiratory','Advanced','A child with an asthma exacerbation becomes exhausted, has reduced conscious level and almost no audible air entry. What does this finding suggest?','["Isolated anxiety without respiratory risk","Life-threatening asthma with impending respiratory failure","Resolution of bronchospasm","Mild asthma suitable for discharge","A normal examination"]',1,'A silent or near-silent chest in a tiring child is an ominous sign because airflow is critically reduced. Escalate urgently for advanced airway and intensive care support.','Global Initiative for Asthma strategy reports','https://ginasthma.org/reports/',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('akp-008','AKP','Respiratory','Intermediate','A toddler has a history of choking while playing, persistent focal wheeze and a normal chest radiograph. What is the best interpretation?','["A normal radiograph completely excludes aspiration","Airway foreign body remains possible despite normal radiography","No further assessment can be justified","Asthma is confirmed","A viral infection is proven"]',1,'Many inhaled foreign bodies are radiolucent. A normal radiograph does not exclude aspiration; clinical suspicion may warrant urgent specialist airway evaluation.','RCPCH theory exam syllabus and structure','https://www.rcpch.ac.uk/education-careers/examinations/theory/structure-syllabi',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('akp-009','AKP','Respiratory','Intermediate','A child has high fever, toxic appearance, stridor and deterioration after a croup-like illness. Which alternative diagnosis is particularly important?','["Uncomplicated viral rhinitis","Physiological infant reflux","Bacterial tracheitis","Exercise-induced bronchospasm","Simple allergic rhinitis"]',2,'Bacterial tracheitis may cause severe upper-airway obstruction, high fever and toxicity, often with poor response to conventional croup treatment; urgent airway review is needed.','RCPCH theory exam syllabus and structure','https://www.rcpch.ac.uk/education-careers/examinations/theory/structure-syllabi',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('akp-010','AKP','Respiratory','Advanced','A child is drooling, sitting forward, febrile and appears frightened with rapidly progressive stridor. What is the safest immediate approach?','["Lay the child flat despite distress","Keep the child calm and summon an experienced airway team urgently","Examine the throat forcefully with a tongue depressor","Obtain an unnecessary blood test before seeking help","Send the child alone to radiology"]',1,'Possible epiglottitis is an airway emergency. Avoid interventions that could provoke obstruction; keep the child calm and arrange specialist controlled airway management.','RCPCH theory exam syllabus and structure','https://www.rcpch.ac.uk/education-careers/examinations/theory/structure-syllabi',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('akp-011','AKP','Neonatology','Advanced','A 2-day-old develops severe shock, weak pulses and metabolic acidosis as the ductus arteriosus closes. What treatment should be considered urgently if a duct-dependent cardiac lesion is suspected?','["Oral iron","Prostaglandin E1 infusion under specialist supervision","Routine inhaled salbutamol","High-dose oral antihistamine","Phototherapy as the sole intervention"]',1,'Duct-dependent systemic circulation can collapse when the ductus closes; prostaglandin E1 may restore ductal patency while urgent neonatal and cardiac care is arranged.','RCPCH theory exam syllabus and structure','https://www.rcpch.ac.uk/education-careers/examinations/theory/structure-syllabi',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('akp-012','AKP','Neonatology','Intermediate','A 4-week-old has a documented temperature of 38.2 °C and appears relatively well. Which general action is most appropriate?','["Reassure by telephone only","Diagnose teething","Give an antipyretic and avoid follow-up","Wait a week without evaluation","Urgent face-to-face assessment because of age and fever"]',4,'A measured temperature of at least 38 °C in an infant younger than 3 months is a high-risk feature requiring urgent clinical assessment for serious bacterial infection.','NICE guideline NG143: Fever in under 5s','https://www.nice.org.uk/guidance/ng143',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('akp-013','AKP','Renal','Advanced','A 5-year-old develops pallor, bruising, oliguria and raised creatinine several days after bloody diarrhoea. Which combination best defines the suspected syndrome?','["Eosinophilia with normal renal function","Microangiopathic haemolytic anaemia, thrombocytopenia and acute kidney injury","Isolated thrombocytopenia only","Nephrotic-range proteinuria with normal platelets","Hyperglycaemia and ketonuria"]',1,'Haemolytic uraemic syndrome is defined by microangiopathic haemolytic anaemia, thrombocytopenia and acute kidney injury; urgent paediatric renal assessment is required.','RCPCH theory exam syllabus and structure','https://www.rcpch.ac.uk/education-careers/examinations/theory/structure-syllabi',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('akp-014','AKP','Renal','Intermediate','A child with IgA vasculitis has palpable purpura and abdominal pain but feels well. Which follow-up measurement is especially important?','["Urinalysis and blood pressure","Thyroid antibodies only","Bone age without examination","Routine serum amylase alone","Visual acuity only"]',0,'Renal involvement in IgA vasculitis can be initially asymptomatic; urine examination and blood pressure monitoring are essential even if the initial presentation is mild.','RCPCH theory exam syllabus and structure','https://www.rcpch.ac.uk/education-careers/examinations/theory/structure-syllabi',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('akp-015','AKP','Endocrinology','Advanced','A child has DKA and a serum potassium concentration that is initially normal. Why is ongoing potassium assessment essential during treatment?','["DKA always causes net potassium excess","Insulin raises potassium by blocking cellular uptake","Total body potassium is depleted and insulin may lower serum potassium","Serum potassium can never change during insulin treatment","Potassium replacement is unnecessary in every child"]',2,'Although initial serum potassium can be normal or high, osmotic losses create total-body potassium depletion. Insulin and correction of acidosis can rapidly lower circulating potassium.','NICE guideline NG18: Diabetes in children and young people','https://www.nice.org.uk/guidance/ng18',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('akp-016','AKP','Endocrinology','Intermediate','A 10-year-old with newly diagnosed type 1 diabetes has deep, laboured breathing, abdominal pain and ketones. What does the breathing pattern likely represent?','["Compensatory hyperventilation for metabolic acidosis","Primary respiratory alkalosis without metabolic disease","A psychogenic sigh as the only cause","Isolated upper-airway obstruction","Normal sleep breathing"]',0,'Kussmaul breathing is deep, laboured hyperventilation that reduces PaCO2 as respiratory compensation for metabolic acidosis in DKA.','NICE guideline NG18: Diabetes in children and young people','https://www.nice.org.uk/guidance/ng18',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('akp-017','AKP','Neurology','Intermediate','A 20-month-old has a single generalized seizure with fever lasting four minutes, returns to baseline and has no focal signs. Which description best fits?','["Simple febrile seizure","Neonatal seizure","Unprovoked epilepsy by definition","Status epilepticus","Complex febrile seizure due to prolonged duration"]',0,'A simple febrile seizure is generalised, lasts less than 15 minutes and occurs only once in 24 hours in a neurologically appropriate age group, followed by recovery.','NICE guideline NG143: Fever in under 5s','https://www.nice.org.uk/guidance/ng143',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('akp-018','AKP','Neurology','Advanced','A child with possible meningitis has declining consciousness and focal neurological deficits. Which statement about immediate lumbar puncture is best?','["LP replaces the need for antibiotics","Only blood pressure is relevant before LP","Defer LP pending stabilization and specialist assessment because of concerning neurological signs","Perform LP immediately irrespective of instability","Imaging always rules out LP risk completely"]',2,'Reduced consciousness or focal signs may indicate increased risk from LP. Stabilisation and urgent antimicrobial treatment take priority, with decisions guided by senior assessment.','NICE guideline NG240: Meningitis and meningococcal disease','https://www.nice.org.uk/guidance/ng240',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('akp-019','AKP','Infectious diseases','Advanced','A febrile 5-year-old refuses to bear weight and has a hot, swollen knee with severe pain on movement. Which diagnosis must be urgently excluded?','["Septic arthritis","Benign hypermobility syndrome","Osgood-Schlatter disease","Growing pains","Simple contusion without examination"]',0,'Septic arthritis can rapidly damage the joint and cause systemic illness. Urgent orthopaedic assessment, cultures and prompt antimicrobial treatment are required.','RCPCH theory exam syllabus and structure','https://www.rcpch.ac.uk/education-careers/examinations/theory/structure-syllabi',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('akp-020','AKP','Infectious diseases','Intermediate','A child has 6 days of fever, oral mucosal changes, bilateral conjunctival injection and swollen feet. Which complication is the principal reason for prompt diagnosis of Kawasaki disease?','["Renal stones","Permanent sensorineural deafness as the defining risk","Portal hypertension","Chronic pulmonary fibrosis","Coronary artery abnormalities"]',4,'Kawasaki disease is associated with coronary arterial inflammation and aneurysms; timely assessment and treatment reduce cardiac complications.','RCPCH theory exam syllabus and structure','https://www.rcpch.ac.uk/education-careers/examinations/theory/structure-syllabi',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('akp-021','AKP','Haematology','Intermediate','A previously healthy child develops petechiae after a viral illness, is clinically well and has isolated marked thrombocytopenia with other blood counts normal. What is the most likely diagnosis?','["Iron deficiency anaemia","Haemolytic uraemic syndrome","Immune thrombocytopenia","Acute leukaemia proven by the description","Disseminated intravascular coagulation"]',2,'Childhood immune thrombocytopenia often causes isolated thrombocytopenia after infection; atypical signs, abnormal blood film or other cytopenias warrant urgent alternative evaluation.','RCPCH theory exam syllabus and structure','https://www.rcpch.ac.uk/education-careers/examinations/theory/structure-syllabi',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('akp-022','AKP','Haematology','Advanced','A child with sickle cell disease develops fever, chest pain, hypoxaemia and a new pulmonary infiltrate. What serious complication is most likely?','["Simple viral rhinitis","Acute chest syndrome","Nephrotic syndrome","Sickle cell trait alone","Uncomplicated vaso-occlusive pain without respiratory involvement"]',1,'Acute chest syndrome features a new lung infiltrate with respiratory symptoms or fever in sickle cell disease. Prompt inpatient treatment and careful monitoring are essential.','RCPCH theory exam syllabus and structure','https://www.rcpch.ac.uk/education-careers/examinations/theory/structure-syllabi',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('akp-023','AKP','Cardiology','Intermediate','A stable child has sudden regular narrow-complex tachycardia, absent obvious P waves and a heart rate far above the expected range. What is the initial non-pharmacological management commonly attempted?','["Routine antibiotics","Age-appropriate vagal manoeuvres while monitoring","Oral diuretic therapy","Immediate unsynchronised shock in every stable child","Forceful carotid sinus massage in an infant"]',1,'Stable supraventricular tachycardia can respond to age-appropriate vagal manoeuvres. If unsuccessful, escalation follows paediatric arrhythmia algorithms.','AHA guidelines for CPR and emergency cardiovascular care','https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('akp-024','AKP','Cardiology','Advanced','A child with severe hyperkalaemia has a widened QRS complex and haemodynamic instability. Which intravenous treatment immediately helps stabilise the myocardium?','["Oral salbutamol syrup","Vitamin D supplementation","Calcium salts administered with cardiac monitoring","Oral iron","Isotonic dextrose alone without insulin"]',2,'Intravenous calcium stabilises the cardiac membrane in hyperkalaemia with ECG changes but does not remove potassium; definitive potassium-lowering measures are also required.','RCPCH theory exam syllabus and structure','https://www.rcpch.ac.uk/education-careers/examinations/theory/structure-syllabi',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('akp-025','AKP','Gastroenterology','Advanced','An adolescent presents with sudden severe unilateral scrotal pain, nausea and a high-riding testis. Which action is essential?','["Antibiotics without examination","Immediate urgent surgical assessment for possible testicular torsion","Reassurance that the pain will resolve","Sports restriction alone","Routine outpatient ultrasound next week"]',1,'Testicular torsion is time-critical and diagnosis is primarily clinical; surgery should not be delayed for imaging when suspicion is high.','RCPCH theory exam syllabus and structure','https://www.rcpch.ac.uk/education-careers/examinations/theory/structure-syllabi',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('akp-026','AKP','Gastroenterology','Intermediate','A school-aged child has migratory abdominal pain that localises to the right iliac fossa with fever and guarding. Which diagnosis is most likely?','["Uncomplicated lactose intolerance","Acute appendicitis","Gastro-oesophageal reflux","Functional abdominal pain without assessment","Infantile pyloric stenosis"]',1,'Appendicitis often begins as vague periumbilical pain before localising to the right iliac fossa, accompanied by tenderness, guarding and systemic signs.','RCPCH theory exam syllabus and structure','https://www.rcpch.ac.uk/education-careers/examinations/theory/structure-syllabi',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('akp-027','AKP','Emergency medicine','Advanced','A child is tachycardic with prolonged capillary refill but has blood pressure within the age-appropriate range after several days of diarrhoea. Which interpretation is most accurate?','["Immediate discharge is always safe","Tachycardia is irrelevant in children","Compensated shock can occur before hypotension","Normal blood pressure excludes shock","Severe dehydration is impossible"]',2,'Children may preserve blood pressure until late in shock through compensatory responses. Perfusion and overall clinical status matter more than a single pressure reading.','NICE guideline NG51: Sepsis','https://www.nice.org.uk/guidance/ng51',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('akp-028','AKP','Emergency medicine','Intermediate','A toddler has reduced urine output, dry mucous membranes and sunken eyes during gastroenteritis but is alert and perfused. Which principle best guides fluid choice?','["Avoid any oral fluids for 24 hours","Start insulin to improve urine output","Use hypotonic intravenous fluid routinely in all cases","Give unrestricted fruit juice as sole therapy","Assess dehydration and use oral rehydration when safely tolerated"]',4,'Oral rehydration solution is often appropriate for mild to moderate dehydration in a child able to drink, with escalation for severe dehydration or shock.','NICE guideline CG84: Gastroenteritis in under 5s','https://www.nice.org.uk/guidance/cg84',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('akp-029','AKP','Infectious diseases','Advanced','A child with suspected meningococcal infection is haemodynamically unstable. Which statement about antimicrobials is most appropriate?','["Do not delay urgent antibiotics for lumbar puncture","Repeat antipyretics for a day before reassessment","Routine outpatient oral therapy is sufficient","Wait for lumbar puncture cultures before all treatment","Antibiotics are contraindicated with rash"]',0,'In suspected invasive bacterial infection or meningococcal sepsis, urgent parenteral antibiotics and resuscitation take priority over nonessential diagnostic procedures.','NICE guideline NG240: Meningitis and meningococcal disease','https://www.nice.org.uk/guidance/ng240',0,1,1795392000,1795392000);
INSERT OR IGNORE INTO questions(id,exam,topic,difficulty,stem,choices_json,answer,explanation,reference_title,reference_url,is_free,is_published,created_at,updated_at) VALUES('akp-030','AKP','Cardiology','Advanced','A neonate with suspected critical congenital heart disease has saturation differences and worsening perfusion. Which specialist investigations are most definitive for defining anatomy?','["Serum iron studies","Electroencephalography","Urgent echocardiography","Abdominal ultrasound","Routine chest x-ray alone"]',2,'Echocardiography defines structural heart disease and shunt physiology. Stabilisation and urgent neonatology or cardiology input should occur without waiting for routine tests.','RCPCH theory exam syllabus and structure','https://www.rcpch.ac.uk/education-careers/examinations/theory/structure-syllabi',0,1,1795392000,1795392000);
